type TimestampType0 = string

// TimestampType1 Gemini strongly recommends using milliseconds instead of seconds for timestamps.
//
// | Timestamp format            | Example                   | Supported request type |
// |-----------------------------|---------------------------|------------------------|
// | whole number (seconds)      | `1495127793`              | `GET`, `POST`          |
